"""3D TET10 / GP-tensor / GPU patch with the detailed solver's strain form."""
from tools.copv_fenicsx_structural import *
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--input',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);args=ap.parse_args();src=np.load(args.input);xyz=src['xyz'];cells=src['cells'];out=args.output;out.mkdir(parents=True,exist_ok=True)
    edges=[(0,1),(1,2),(2,0),(0,3),(2,3),(1,3)];top=basix.topology(basix.CellType.tetrahedron);perm=[0,1,2,3]+[4+next(i for i,e in enumerate(edges) if set(e)==set(edge)) for edge in top[1]];el=basix.ufl.element('Lagrange','tetrahedron',2,shape=(3,),lagrange_variant=basix.LagrangeVariant.equispaced);domain=mesh.create_mesh(MPI.COMM_SELF,cells[:,perm].astype(np.int64),ufl.Mesh(el),xyz);V=fem.functionspace(domain,el);coord=V.tabulate_dof_coordinates();_,order=cKDTree(xyz).query(coord);qp,qw=basix.make_quadrature(basix.CellType.tetrahedron,4)
    QS=fem.functionspace(domain,basix.ufl.quadrature_element('tetrahedron',value_shape=(3,3),degree=4,scheme='default'));Q=fem.Function(QS);Q.x.array.reshape(-1,9)[:]=src['Q'].reshape(1,9);CS=fem.functionspace(domain,basix.ufl.element('DG','tetrahedron',0,shape=(6,6)));C=fem.Function(CS);C.x.array[:]=src['C_local'].ravel();u=ufl.TrialFunction(V);v=ufl.TestFunction(V)
    def strain(w):return eng(Q.T*ufl.sym(ufl.grad(w))*Q)
    a=fem.form(ufl.dot(strain(v),C*strain(u))*ufl.Measure('dx',domain=domain,metadata={'quadrature_degree':4}));g=fem.Function(V);g.x.array[:]=src['expected_U'][order].ravel();bc=fem.dirichletbc(g,np.flatnonzero(order<4).astype(np.int32));A=fp.assemble_matrix(a,bcs=[bc]);A.assemble();b=A.createVecRight();b.array[:]=src['force_N'][order].ravel();fp.apply_lifting(b,[a],bcs=[[bc]]);fp.set_bc(b,[bc]);gpu=A.convert('aijcusparse');rhs=PETSc.Vec().createSeq(len(b.array),comm=MPI.COMM_SELF);rhs.setType('cuda');rhs.array[:]=b.array;x=rhs.duplicate();ksp=PETSc.KSP().create(MPI.COMM_SELF);ksp.setOperators(gpu);ksp.setType('cg');ksp.getPC().setType('jacobi');ksp.setTolerances(rtol=1e-13,max_it=1000);ksp.solve(rhs,x)
    if ksp.getConvergedReason()<=0:raise RuntimeError('Patch CUDA solve failed')
    field=fem.Function(V);field.x.array[:]=x.array;local=fem.Expression(C*strain(field),qp).eval(domain,np.array([0],np.int32)).reshape(-1,6);pairs=[(0,0),(1,1),(2,2),(1,2),(0,2),(0,1)];tensor=np.zeros((len(local),3,3))
    for j,(i,k) in enumerate(pairs):tensor[:,i,k]=local[:,j];tensor[:,k,i]=local[:,j]
    s=src['Q']@tensor@src['Q'].T;stress=np.stack([s[:,i,j] for i,j in pairs],axis=-1);U=np.empty_like(src['expected_U']);U[order]=x.array.reshape(-1,3);err=float(np.linalg.norm(U-src['expected_U'])/np.linalg.norm(src['expected_U']));serr=float(np.linalg.norm(stress-src['expected_stress_xyz'])/np.linalg.norm(np.broadcast_to(src['expected_stress_xyz'],stress.shape)));report=dict(U_relative_L2=err,stress_relative_L2=serr,matrix_type=gpu.getType(),vector_type=x.getType(),iterations=ksp.getIterationNumber(),passed=err<1e-9 and serr<1e-9);write(out/'fenicsx_review.json',report);print(json.dumps(report))
    if not report['passed']:raise RuntimeError('3D analytical patch failed')
if __name__=='__main__':main()
